Here is the original Java 8 code you have to rewrite:
<original_code>
import java.util.* ;

public class Solution{

    public static void main(String[] args){

        Scanner in = new Scanner(System.in) ;
        int n = in.nextInt() ;
        int B = in.nextInt() ;
        int[] a = new int[n] ;

        for(int i=0;i<n;i++){
            a[i] = in.nextInt() ;
        }

        int c0 =0,c1 = 0;
        PriorityQueue<Integer> q = new PriorityQueue<Integer>() ;

        for(int i=0;i<n;i++){
            if(a[i] % 2 == 0){
                c0 ++ ;
            }else{
                c1 ++ ;
            }

            if(c0 == c1 && i < n-1){
                q.add( Math.abs(a[i+1] - a[i]) ) ;
            }

        }

         int cnt =0,sum = 0;

            while(!q.isEmpty() && sum + q.peek() <=  B){
                sum += q.poll() ;
                cnt++;
            }

            System.out.println(cnt) ;
    }

}
